import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { completeOrderWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await completeOrderWorkflow(req.scope)
    .run({
      input: {
        orderIds: ["order_1", "order_2"],
        additional_data: {
          send_webhook: true,
        }
      }
    })

  res.send(result)
}

import {
