export default async function handleOrderPlaced({
  event: { data },
  container,
}: SubscriberArgs < { id: string } > ) {
  const { result } = await completeOrderWorkflow(container)
    .run({
      input: {
        orderIds: ["order_1", "order_2"],
        additional_data: {
          send_webhook: true,
        }
      }
    })

  console.log(result)
}

